+const form = document.querySelector(".consent-form");
+const checkbox = document.querySelector("#terms-consent");
+const errorText = document.querySelector("#terms-error");
+const statusMessage = document.querySelector(".status-message");
+
+function showError(message) {
+  checkbox.setAttribute("aria-invalid", "true");
+  errorText.textContent = message;
+  statusMessage.textContent = "";
+}
+
+function clearError() {
+  checkbox.removeAttribute("aria-invalid");
+  errorText.textContent = "";
+}
+
+form.addEventListener("submit", (event) => {
+  event.preventDefault();
+
+  if (!checkbox.checked) {
+    showError("Check this box to agree before submitting.");
+    checkbox.focus();
+    return;
+  }
+
+  clearError();
+  statusMessage.textContent = "Agreement submitted.";
+});
+
+checkbox.addEventListener("change", () => {
+  if (checkbox.checked) {
+    clearError();
+  }
+});
